    spark.stop()
  }
}

import org.apache.spark.sql.SparkSession
object InformeCiudades {
  def main(args: Array[String]): Unit = {
    val spark = SparkSession.builder().appName("InformeCiudades").getOrCreate()
    import spark.implicits._
    val datos = Seq(
      (1, "2025-01-05", "Ana", "Santiago", "Tecnologia", 150000.0),
      (2, "2025-01-06", "Luis", "Valparaiso", "Hogar", 85000.0),
      (3, "2025-02-07", "Carla", "Concepcion", "Tecnologia", 210000.0),
      (4, "2025-02-08", "Pedro", "Santiago", "Tecnologia", 95000.0),
      (5, "2025-03-09", "Maria", "Temuco", "Tecnologia", 180000.0),
      (6, "2025-03-10", "Diego", "Santiago", "Hogar", 120000.0)
    )
    val ventas = datos.toDF("id_venta", "fecha", "cliente", "ciudad", "categoria", "monto")
    ventas.createOrReplaceTempView("ventas")
    // DECISIÓN: filtrar antes de promediar por ciudad.
    spark.sql("""SELECT ciudad, AVG(monto) AS promedio FROM ventas WHERE categoria = 'Tecnologia' GROUP BY ciudad ORDER BY promedio DESC""").show()
    // INTERPRETACIÓN: se esperan Concepcion 210000, Temuco 180000 y Santiago 122500.
    spark.stop()
  }
}
